query {
  viewer {
    accounts(filter: {accountTag: "${accountTag}"}) {
      storage: d1StorageAdaptiveGroups(orderBy: [date_DESC], limit: 1000, filter: {date_geq: "${__from:date:YYYY-MM-DD}",date_leq: "${__to:date:YYYY-MM-DD}",}) {
        max {
          databaseSizeBytes
        }
        dimensions {
          databaseId
          datetimeHour
          date
        }
      }
    }
  }
}

